import {useMutation, useQueryClient} from '@github-ui/react-query'
import type {
  CreateTaskParams,
  CreateJobParams,
  UnhydratedTask,
  OptimisticTask,
  CreateTaskMutationParams,
} from '../types/task'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {fetchCAPI} from '../utils/fetch-capi'
import {uuid} from '../utils/uuid'
import {agentTasksQueryKey} from './useTasks'

export function useCreateTask({onError}: {onError?: (error: Error, variables: CreateTaskMutationParams) => void}) {
  const queryClient = useQueryClient()
  const isBranchSelectionEnabled = isFeatureEnabled('copilot_immersive_agent_branch_selection')

  const createTaskMutation = useMutation<string, Error, CreateTaskMutationParams>({
    mutationKey: ['createTask'],
    onMutate: async (params: CreateTaskMutationParams) => {
      // Cancel any existing refetches (prevents race conditions)
      await queryClient.cancelQueries({queryKey: agentTasksQueryKey})

      // Snapshot the previous value for potential rollback
      const previousTasks = queryClient.getQueryData<Array<UnhydratedTask | OptimisticTask>>(agentTasksQueryKey) ?? []

      // Add optimistic task to cache
      const optimisticTask = createOptimisticTask(params)
      queryClient.setQueryData(agentTasksQueryKey, [optimisticTask, ...previousTasks])

      // Return context for potential rollback
      return {previousTasks}
    },
    mutationFn: async (params: CreateTaskMutationParams) => {
      const response = await createJob({
        ...params,
        isBranchSelectionEnabled,
        title: params.problemStatement,
      })
      if (!response.ok) {
        throw new Error(`Failed to create task: ${params.clientGeneratedId}`)
      }

      return params.clientGeneratedId
    },
    onError: (error, variables) => {
      // Only remove the specific failed task, there could be many in flight at the same time
      const currentTasks = queryClient.getQueryData<Array<UnhydratedTask | OptimisticTask>>(agentTasksQueryKey) ?? []
      const tasksWithoutFailed = currentTasks.filter(task => task.clientGeneratedId !== variables.clientGeneratedId)
      queryClient.setQueryData(agentTasksQueryKey, tasksWithoutFailed)

      // Call the passed callback with returned error and original variables
      onError?.(error, variables)
    },
    onSuccess: () => {
      // Invalidate and refetch tasks query to warm up the cache
      queryClient.invalidateQueries({queryKey: agentTasksQueryKey})
    },
  })

  const createTask = (params: CreateTaskParams, clientTaskId?: string) => {
    const clientGeneratedId = clientTaskId ?? uuid()
    createTaskMutation.mutate({...params, clientGeneratedId})
  }

  return {
    createTask,
    isCreating: createTaskMutation.isPending,
    createError: createTaskMutation.error,
  }
}

// Helper function to create job via the Jobs API
async function createJob({
  clientGeneratedId,
  nwo,
  problemStatement,
  baseRef,
  isBranchSelectionEnabled,
  eventType,
  title,
  reference,
  subagent,
}: CreateJobParams): Promise<Response> {
  const endpoint = `/agents/swe/jobs/${nwo}`
  const isFileReferenceEnabled = isFeatureEnabled('copilot_agent_tasks_btn_file_reference')
  const referenceString = reference && isFileReferenceEnabled ? `On ${reference}, ` : ''

  return await fetchCAPI({
    path: endpoint,
    method: 'POST',
    body: {
      problem_statement: referenceString + problemStatement,
      pull_request: {
        ...(isBranchSelectionEnabled && baseRef && {base_ref: `refs/heads/${baseRef}`}),
        ...(title && {title}),
      },
      event_identifiers: [clientGeneratedId],
      event_type: eventType,
      subagent,
    },
  })
}

function createOptimisticTask({
  clientGeneratedId,
  nwo,
  problemStatement,
  baseRef,
  eventType,
  subagent,
}: CreateTaskMutationParams): OptimisticTask {
  return {
    resource_type: 'pull',
    resource_id: -1, // Placeholder until we get real ID from server
    session_count: 1,
    latest_session_updated_at: new Date().toISOString(),
    latest_session_state: 'in_progress',
    event_identifiers: [clientGeneratedId],
    event_type: eventType,
    isOptimistic: true,
    clientGeneratedId,
    nwo,
    problemStatement,
    baseRef,
    subagent,
  }
}
